// Extract all ytIds from the JS file content
const raw = $input.first().json.data || $input.first().json.body || '';
const content = typeof raw === 'string' ? raw : JSON.stringify(raw);

const matches = [...content.matchAll(/ytId:\s*['"]([ A-Za-z0-9_-]{6,})['"]\s*[,}]/g)];
const ids = [...new Set(matches.map(m => m[1].trim()).filter(id => id && id.length >= 6))];

console.log(`Found ${ids.length} unique ytIds`);
return [{ json: { ytIds: ids, total: ids.length } }];

// Split ytIds into batches of 50 for the verify endpoint
const allIds = $input.first().json.ytIds || [];
const batchSize = 50;
const batches = [];
for (let i = 0; i < allIds.length; i += batchSize) {
  batches.push({ json: { ytIds: allIds.slice(i, i + batchSize), batchNum: Math.floor(i/batchSize)+1 } });
}
console.log(`Split into ${batches.length} batches`);
return batches;

// Aggregate results from all batches
const items = $input.all();
const dead = [];
const restricted = [];
let ok = 0;
let total = 0;

for (const item of items) {
  const d = item.json;
  ok += d.ok || 0;
  total += d.total || 0;
  if (d.dead?.length) dead.push(...d.dead);
  if (d.restricted?.length) restricted.push(...d.restricted);
}

console.log(`Verify results: ${ok} ok, ${dead.length} dead, ${restricted.length} restricted`);

return [{ json: {
  checked: total,
  ok,
  dead,
  restricted,
  issues_found: dead.length + restricted.length,
  checked_at: new Date().toISOString()
}}];

// Format report
const d = $input.first().json;
const lines = [
  `📊 Rapport bibliothèque — ${d.checked_at?.slice(0,10)}`,
  `✅ OK: ${d.ok} / ${d.checked}`,
  d.dead.length    ? `❌ Morts (${d.dead.length}): ${d.dead.slice(0,10).join(', ')}${d.dead.length>10?' ...':''}` : null,
  d.restricted.length ? `🔒 Restreints (${d.restricted.length}): ${d.restricted.slice(0,10).join(', ')}` : null,
  '',
  d.dead.length ? 'Action: supprimer ou remplacer les IDs morts dans videos-data.js' : ''
].filter(l => l !== null);

console.log(lines.join('\n'));
return [{ json: { ...d, report: lines.join('\n') } }];

// All good — log and end
console.log('✅ Library OK — no dead/restricted videos found');
return $input.all();
